        (void*)0x03   // HIP_LAUNCH_PARAM_END
    };

    // Grid: persistent mode, one block per work unit
    unsigned int gdx = (unsigned int)(work_indptr.size(0) - 1);

    // KEY: at::cuda::getCurrentCUDAStream() returns the HARNESS stream
    // This is why load_inline works where ctypes failed!
    hipStream_t stream = at::cuda::getCurrentCUDAStream();

    hipError_t err = hipModuleLaunchKernel(
        s_mla_func,
        gdx, 1, 1,     // grid
        256, 1, 1,      // block (4 wavefronts of 64)
        0,              // shared memory
        stream,         // CORRECT stream from harness
        nullptr,        // kernelParams (nullptr for BUFFER_POINTER)
        config          // extra config with packed args
    );

    return (err == hipSuccess) ? 0 : (int)err;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("launch_mla_stage1", &launch_mla_stage1, "Direct .co MLA stage1 dispatch");
}
"""

CPP_SOURCE = """
int launch_mla_stage1(
    torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor,
    torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor,
    torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor,
    torch::Tensor, float, int, int, int
);
"""

os.environ["CXX"] = "clang++"

try:
    _module = load_inline(
        name="mla_co_dispatch",
        cpp_sources=[CPP_SOURCE],
        cuda_sources=[HIP_SOURCE],
        functions=["launch_mla_stage1"],
        verbose=False,
        extra_cuda_cflags=["--offload-arch=gfx950", "-std=c++20", "-O3"],
    )
    HAS_CO_DISPATCH = True
except Exception as e:
    print(f"[co_dispatch] load_inline failed: {e}")
    HAS_CO_DISPATCH = False

# ─── Cached metadata ──────────────────────────────────────────────
_cache: dict = {}


def _quantize_fp8(tensor: torch.Tensor):
    finfo = torch.finfo(FP8_DTYPE)
    amax = tensor.abs().amax().clamp(min=1e-12)
    scale = amax / finfo.max
    return (
        (tensor / scale).clamp(finfo.min, finfo.max).to(FP8_DTYPE),
        scale.float().reshape(1),
    )


def _choose_splits(total_kv: int) -> int:
    if total_kv <= 2048:
        return 4
    if total_kv <= 16384:
        return 8
    if total_kv <= 131072:
        return 16
    return 16


def _build_metadata(bs, qseqlen, nheads, q_dtype, kv_dtype, num_splits, qo_indptr, kv_indptr, kvseqlen):
    total_kv = bs * kvseqlen
    kv_indices = torch.arange(total_kv, dtype=torch.int32, device="cuda")
    kv_last_page_len = (kv_indptr[1:] - kv_indptr[:-1]).to(torch.int32)

    info = get_mla_metadata_info_v1(
        bs, qseqlen, nheads, q_dtype, kv_dtype,
        is_sparse=False, fast_mode=False,
        num_kv_splits=num_splits, intra_batch_mode=True,
    )
    work = [torch.empty(s, dtype=t, device="cuda") for s, t in info]
    wm, wi, wis, ri, rfm, rpm = work

    get_mla_metadata_v1(
        qo_indptr, kv_indptr, kv_last_page_len,
        nheads // NUM_KV_HEADS, NUM_KV_HEADS, True,
        wm, wis, wi, ri, rfm, rpm,
        page_size=PAGE_SIZE, kv_granularity=16,
        max_seqlen_qo=qseqlen, uni_seqlen_qo=qseqlen,
        fast_mode=False, max_split_per_batch=num_splits,
        intra_batch_mode=True, dtype_q=q_dtype, dtype_kv=kv_dtype,
    )

    total_q = bs * qseqlen
    buf_ns = max(num_splits, 16)
    return {
        "kv_indices": kv_indices,
        "kv_last_page_len": kv_last_page_len,
        "wm": wm, "wi": wi, "wis": wis,
        "ri": ri, "rfm": rfm, "rpm": rpm,
        "logits": torch.empty((buf_ns, total_q, nheads, V_HEAD_DIM), dtype=torch.float32, device="cuda"),
        "attn_lse": torch.empty((buf_ns, total_q, nheads), dtype=torch.float32, device="cuda"),
        "out": torch.empty((total_q, nheads, V_HEAD_DIM), dtype=torch.bfloat16, device="cuda"),
    }


def _get_meta(bs, qseqlen, kvseqlen, q_dtype, kv_dtype, num_splits, qo_indptr, kv_indptr):
    key = (bs, qseqlen, kvseqlen, q_dtype, kv_dtype, num_splits)
    if key not in _cache:
        _cache[key] = _build_metadata(
            bs, qseqlen, NUM_HEADS, q_dtype, kv_dtype,
            num_splits, qo_indptr, kv_indptr, kvseqlen,
        )
    return _cache[key]


def _einsum_attention(data: input_t) -> output_t:
    """Einsum for small batch sizes (same as main submission)."""
    q, kv_data, qo_indptr, kv_indptr, config = data
    bs = config["batch_size"]
    kvseqlen = config["kv_seq_len"]
    nheads = config["num_heads"]

    kv = kv_data["bf16"].view(bs, kvseqlen, QK_HEAD_DIM)
    q_r = q.view(bs, 1, nheads, QK_HEAD_DIM)

    scores = torch.einsum("bqnh,bsh->bnqs", q_r, kv).mul_(SM_SCALE)
    weights = torch.softmax(scores, dim=-1)
    v = kv[:, :, :V_HEAD_DIM]
    out = torch.einsum("bnqs,bsd->bqnd", weights, v)
    return out.reshape(-1, nheads, V_HEAD_DIM).to(torch.bfloat16)


def _co_dispatch_attention(data: input_t) -> output_t:
    """Direct .co kernel dispatch — bypasses Python dispatch overhead."""
    q, kv_data, qo_indptr, kv_indptr, config = data
    bs = config["batch_size"]
    qseqlen = config["q_seq_len"]
    kvseqlen = config["kv_seq_len"]
    total_kv = bs * kvseqlen

    kv_fp8, kv_scale = kv_data["fp8"]
    q_fp8, q_scale = _quantize_fp8(q)

    num_splits = _choose_splits(total_kv)
    kv_4d = kv_fp8.view(kv_fp8.shape[0], PAGE_SIZE, NUM_KV_HEADS, QK_HEAD_DIM)

    meta = _get_meta(bs, qseqlen, kvseqlen, q_fp8.dtype, kv_fp8.dtype, num_splits, qo_indptr, kv_indptr)

    gqa_ratio = NUM_HEADS // NUM_KV_HEADS

    # Stage 1: Direct .co dispatch (eliminates ~20µs Python overhead)
    ret = _module.launch_mla_stage1(
        meta["logits"], meta["attn_lse"],
        q_fp8.view(-1, NUM_HEADS, QK_HEAD_DIM),
        kv_4d, kv_indptr, meta["kv_indices"], meta["kv_last_page_len"],
        qo_indptr, meta["wm"], meta["wi"], meta["out"],
        q_scale, kv_scale,
        SM_SCALE, qseqlen, num_splits, gqa_ratio,
    )

    if ret != 0:
        raise RuntimeError(f"MLA .co dispatch failed with error {ret}")

    # Stage 2: reduce (still via aiter Python — .so, not .co)
    mla_reduce_v1(
        meta["logits"], meta["attn_lse"],
        meta["ri"], meta["rfm"], meta["rpm"],
        qseqlen, meta["out"],
    )

    return meta["out"]


def _fallback_attention(data: input_t) -> output_t:
    """Fallback to standard aiter dispatch if .co dispatch unavailable."""
    from aiter.mla import mla_decode_stage1_asm_fwd

    q, kv_data, qo_indptr, kv_indptr, config = data
    bs = config["batch_size"]
    qseqlen = config["q_seq_len"]
    kvseqlen = config["kv_seq_len"]
    total_kv = bs * kvseqlen

    kv_fp8, kv_scale = kv_data["fp8"]
    q_fp8, q_scale = _quantize_fp8(q)

    num_splits = _choose_splits(total_kv)
    kv_4d = kv_fp8.view(kv_fp8.shape[0], PAGE_SIZE, NUM_KV_HEADS, QK_HEAD_DIM)

    meta = _get_meta(bs, qseqlen, kvseqlen, q_fp8.dtype, kv_fp8.dtype, num_splits, qo_indptr, kv_indptr)

    mla_decode_stage1_asm_fwd(
        q_fp8.view(-1, NUM_HEADS, QK_HEAD_DIM),
        kv_4d, qo_indptr, kv_indptr,
        meta["kv_indices"], meta["kv_last_page_len"],
        None, meta["wm"], meta["wi"], meta["wis"],
        qseqlen, PAGE_SIZE, NUM_KV_HEADS, SM_SCALE,
        meta["logits"], meta["attn_lse"], meta["out"],
        q_scale=q_scale, kv_scale=kv_scale,
    )
    mla_reduce_v1(
        meta["logits"], meta["attn_lse"],
        meta["ri"], meta["rfm"], meta["rpm"],
        qseqlen, meta["out"],
    )
    return meta["out"]


def custom_kernel(data: input_t) -> output_t:
    """MLA with .co dispatch for stage1 (bypasses stream isolation)."""
    _, _, _, _, config = data
    bs = config["batch_size"]
    kvseqlen = config["kv_seq_len"]
    total_kv = bs * kvseqlen

    # Small shapes: einsum (no dispatch overhead)
    if bs <= MATMUL_MAX_BS or total_kv <= MATMUL_MAX_TOTAL_KV:
        return _einsum_attention(data)

    # Large shapes: .co dispatch or fallback
    if HAS_CO_DISPATCH:
        try:
            return _co_dispatch_attention(data)
        except RuntimeError:
            pass

    return _fallback_attention(data)
